class profile_postgresql::repo {

  include apt

  apt::source { 'pgdg':
    location => lookup('profile_postgresql::repo_location'),
    release  => lookup('profile_postgresql::repo_release'),
    repos    => 'main',
    key      => {
      id     => lookup('profile_postgresql::repo_key_id'),
      source => lookup('profile_postgresql::repo_key_source'),
    },
  }
}

class profile_postgresql::install {

  package { $profile_postgresql::package_names:
    ensure  => installed,
    require => Class['profile_postgresql::repo'],
  }

  package { 'libpq-dev':
    ensure => installed,
  }
}

class profile_postgresql::service {

  service { $profile_postgresql::service_name:
    ensure  => running,
    enable  => true,
    require => Class['profile_postgresql::install'],
  }
}

class role::app_server {
  include profile::base::base
  include profile::loadbalancer::haproxy
  include profile::app::stack
  include profile::cache::redis
}

# Role: Application stack node (Python app + PostgreSQL)
class role::app_stack {
  if $facts['kernel'].downcase == 'linux' {
    Exec {
      path => '/usr/bin:/bin:/usr/sbin:/sbin',
    }
  }

  include ::profile::base::base
  contain ::profile::app::stack

  Class['::profile::base::base'] -> Class['::profile::app::stack']
}

# Profile: Application stack (Python + PostgreSQL)
# Thin wrapper that delegates to the profile_app_stack module.
class profile::app::stack (
  Optional[String] $environment_name = fact('environment'),
) {
  class { 'profile_app_stack': }
}

# Base OS profile — included by all roles.
# Handles common OS-level configuration shared across all node types.
class profile::base::base (
  Boolean $manage_ntp     = lookup('profile::base::manage_ntp', Boolean, 'first', true),
  Boolean $manage_syslog  = lookup('profile::base::manage_syslog', Boolean, 'first', true),
  Boolean $manage_utils   = lookup('profile::base::manage_utils', Boolean, 'first', true),
) {

  if $manage_utils {
    include base_utils
  }

  if $manage_ntp and $facts['kernel'] == 'Linux' {
    package { 'chrony':
      ensure => installed,
    }
    service { 'chronyd':
      ensure => running,
      enable => true,
    }
  }

  if $manage_syslog and $facts['kernel'] == 'Linux' {
    package { 'rsyslog':
      ensure => installed,
    }
    service { 'rsyslog':
      ensure => running,
      enable => true,
    }
  }
}
